const MCP_BASE = ($env.MCP_URL || 'http://mcp-tools:8000/mcp').replace(/\/mcp\/?$/, '');
const SERVICE_TOKEN = $env.SERVICE_TOKEN || '';

const callMcpTool = async (name, args = {}) => {
  const raw = await this.helpers.httpRequest({
    method: 'POST',
    url: `${MCP_BASE}/mcp`,
    headers: {
      'Accept': 'application/json, text/event-stream',
      'Content-Type': 'application/json',
      'X-Service-Token': SERVICE_TOKEN,
    },
    body: {
      jsonrpc: '2.0',
      id: Date.now(),
      method: 'tools/call',
      params: { name, arguments: args },
    },
    json: true,
    timeout: 60000,
  });
  const payload = typeof raw === 'string'
    ? JSON.parse((raw.split('\n').find(l => l.startsWith('data:')) || 'data: {}').replace(/^data:\s*/, ''))
    : raw;
  const sc = payload?.result?.structuredContent;
  if (sc && typeof sc === 'object') return sc.result || sc;
  const txt = payload?.result?.content?.[0]?.text;
  if (txt) {
    try { return JSON.parse(txt); } catch (e) { return { ok: true, text: txt }; }
  }
  return payload?.result || payload || {};
};

const callRouterHttp = async (path, body = null, method = 'POST') => {
  const opts = {
    method,
    url: `${MCP_BASE}/router/${path}`,
    headers: { 'X-Service-Token': SERVICE_TOKEN },
    json: true,
    timeout: 10000,
  };
  if (body !== null && method !== 'GET') opts.body = body;
  return await this.helpers.httpRequest(opts);
};

const extractJsonObject = (rawText) => {
  const cleaned = String(rawText || '').replace(/<think>[\s\S]*?<\/think>/g, '').replace(/<\/?think>/g, '').replace(/```(?:json)?/gi, '').trim();
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('El modelo no devolvió un bloque JSON válido');
  return JSON.parse(match[0]);
};

const incoming = $input.first().json;
const headers = Object.fromEntries(
  Object.entries(incoming.headers || {}).map(([k, v]) => [k.toLowerCase(), v])
);
const body = incoming.body || incoming;

const givenToken = headers['x-webhook-token'] || headers['x-api-key'] || headers['x-service-token'] || '';
const validWebhook = $env.N8N_WEBHOOK_TOKEN && givenToken === $env.N8N_WEBHOOK_TOKEN;
const validService = $env.SERVICE_TOKEN && givenToken === $env.SERVICE_TOKEN;
if (!validWebhook && !validService) {
  return [{
    json: {
      valid: false,
      status_code: 401,
      error: { code: 'UNAUTHORIZED', message: 'Token de webhook ausente o inválido', details: {} },
    },
  }];
}

const mode = String(body.mode || (body.job_id && !body.profile_id ? 'company' : 'student')).toLowerCase();
const cfgRes = await callMcpTool('get_agent_settings');
const cfg = cfgRes.data || cfgRes || {};
const recoCfg = cfg.recommendations || {};

if (mode === 'student') {
  const profileId = String(body.profile_id || '');
  if (!profileId) {
    return [{
      json: {
        valid: false,
        status_code: 400,
        error: { code: 'INVALID_INPUT', message: 'profile_id es obligatorio para mode=student', details: {} },
      },
    }];
  }

  const profileRes = await callMcpTool('get_profile', { profile_id: profileId });
  if (!profileRes.ok) {
    return [{ json: { valid: false, status_code: 404, error: profileRes.error } }];
  }

  let jobs = [];
  if (body.job_id) {
    const singleJob = await callMcpTool('get_job', { job_id: String(body.job_id) });
    if (!singleJob.ok) return [{ json: { valid: false, status_code: 404, error: singleJob.error } }];
    jobs = [singleJob];
  } else {
    const jobsRes = await callMcpTool('list_active_jobs', { limit: Number(recoCfg.max_jobs_per_student || 5) });
    jobs = jobsRes.data || [];
  }

  const ruleMatches = [];
  const allMissingNames = new Set();
  for (const job of jobs) {
    const jid = job.id || job.job_id;
    const matchRes = await callMcpTool('compute_match', { profile_id: profileId, job_id: jid });
    const missRes = await callMcpTool('missing_skills', { profile_id: profileId, job_id: jid });
    const missingList = missRes.data || [];
    for (const m of missingList) {
      if (m.skill) allMissingNames.add(m.skill);
    }
    ruleMatches.push({
      job_id: jid,
      title: job.title,
      score: matchRes.score,
      excluding_failed: matchRes.excluding_failed || [],
      criteria_breakdown: matchRes.criteria_breakdown || {},
      missing_skills: missingList,
      origin: 'RULES',
      engine_version: matchRes.engine_version || '1.0.0',
    });
  }

  ruleMatches.sort((a, b) => Number(b.score || 0) - Number(a.score || 0));
  const topMatch = ruleMatches[0] || null;
  const coursesRes = await callMcpTool('search_courses', {
    skills: Array.from(allMissingNames),
    limit: Number(recoCfg.max_items_per_job || 5),
  });
  const courses = coursesRes.data || [];

  const sourcePayload = {
    profile: profileRes,
    jobs,
    rule_based_matches: ruleMatches,
    available_courses: courses,
  };
  const sourceText = JSON.stringify(sourcePayload, null, 2);

  return [{
    json: {
      valid: true,
      mode: 'student',
      profile_id: profileId,
      primary_job_id: topMatch ? topMatch.job_id : 'job-general',
      rule_based: {
        origin: 'RULES',
        engine_version: '1.0.0',
        matches: ruleMatches,
      },
      task: 'recommend_student',
      agent: 'training_advisor',
      role: 'default',
      perfil_mcp: 'postulante',
      schema_name: 'student_recommendations',
      source_text: sourceText,
      expected_score: topMatch ? topMatch.score : null,
      reported_score: topMatch ? topMatch.score : null,
      prompt_version: '1.0.0',
      user_prompt: `Generá hasta ${recoCfg.max_items_per_job || 5} recomendaciones accionables en JSON ({"items":[...]}) para el estudiante ${profileId} a partir de estos resultados calculados por reglas y cursos disponibles:\n\n${sourceText}`,
    },
  }];
}

if (mode === 'company') {
  const jobId = String(body.job_id || '');
  if (!jobId) {
    return [{
      json: {
        valid: false,
        status_code: 400,
        error: { code: 'INVALID_INPUT', message: 'job_id es obligatorio para mode=company', details: {} },
      },
    }];
  }

  const jobRes = await callMcpTool('get_job', { job_id: jobId });
  if (!jobRes.ok) {
    return [{ json: { valid: false, status_code: 404, error: jobRes.error } }];
  }

  const profilesRes = await callMcpTool('list_candidate_profiles', {
    limit: Number(recoCfg.max_profiles_per_job || 5),
  });
  const profiles = profilesRes.data || [];

  const rankedCandidates = [];
  for (const prof of profiles) {
    const pid = prof.id || prof.profile_id;
    const matchRes = await callMcpTool('compute_match', { profile_id: pid, job_id: jobId });
    const missRes = await callMcpTool('missing_skills', { profile_id: pid, job_id: jobId });
    rankedCandidates.push({
      profile_id: pid,
      full_name: prof.full_name,
      skills: prof.skills || [],
      experience_years: prof.experience_years || 0,
      score: matchRes.score,
      excluding_failed: matchRes.excluding_failed || [],
      missing_skills: missRes.data || [],
      origin: 'RULES',
      engine_version: matchRes.engine_version || '1.0.0',
    });
  }

  rankedCandidates.sort((a, b) => Number(b.score || 0) - Number(a.score || 0));
  const topCandidate = rankedCandidates[0] || null;

  const sourcePayload = {
    job: jobRes,
    ranked_candidates_by_rules: rankedCandidates,
  };
  const sourceText = JSON.stringify(sourcePayload, null, 2);

  return [{
    json: {
      valid: true,
      mode: 'company',
      job_id: jobId,
      primary_profile_id: topCandidate ? topCandidate.profile_id : 'prof-none',
      rule_based: {
        origin: 'RULES',
        engine_version: '1.0.0',
        job_id: jobId,
        candidates: rankedCandidates,
      },
      task: 'recommend_company',
      agent: 'company_advisor',
      role: 'default',
      perfil_mcp: 'empresa',
      schema_name: 'company_recommendations',
      source_text: sourceText,
      expected_score: topCandidate ? topCandidate.score : null,
      reported_score: topCandidate ? topCandidate.score : null,
      prompt_version: '1.0.0',
      user_prompt: `Generá el resumen ejecutivo y justificación por candidato en JSON ({"summary":"...","candidates":[...]}) respetando el score exacto calculado por reglas para la oferta ${jobId}:\n\n${sourceText}`,
    },
  }];
}

return [{
  json: {
    valid: false,
    status_code: 400,
    error: { code: 'INVALID_INPUT', message: "mode debe ser 'student' o 'company'", details: { mode } },
  },
}];

