  const cleaned = String(rawText || '').replace(/<think>[\s\S]*?<\/think>/g, '').replace(/<\/?think>/g, '').replace(/```(?:json)?/gi, '').trim();
  const match = cleaned.match(/\{[\s\S]*\}/);
